'use strict';
const D=window.LAB_DATA;
const STORAGE='english-lab-klasse-7-v1';
const $=(s,root=document)=>root.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const defaults=()=>({answers:{},plan:{},session:null,exams:{},missions:{}});
let state=defaults(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(raw&&raw.version===1&&raw.data&&typeof raw.data==='object'){state={...defaults(),...raw.data};for(const k of ['answers','plan','exams','missions'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};if(state.session&&(!Array.isArray(state.session.ids)||!Number.isInteger(state.session.index)||state.session.index<0||state.session.ids.some(id=>!D.questions.some(q=>q.id===id))))state.session=null;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({version:1,data:state}));return true;}catch{storageOK=false;notify('Der Browser kann gerade nicht speichern. Exportiere deine Texte und deinen Fortschritt.');return false;}}
let toastId;
function notify(message){const n=$('#notice');n.textContent=message;n.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>n.classList.remove('show'),5000);}
const topic=id=>D.grammar.find(t=>t.id===id);
const year=y=>D.years.find(t=>t.year===Number(y))||D.years[0];
const asset=(file,page)=>`material/${encodeURIComponent(file)}${page?'#page='+page:''}`;
const pdfLink=(file,label,page)=>file?`<a href="${asset(file,page)}" target="_blank" rel="noopener">${E(label)} ↗</a>`:'';
const button=(label,action,kind='primary',extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const head=(title,sub,kicker='')=>`${kicker?`<p class="section-label">${kicker}</p>`:''}<h1>${title}</h1><p class="intro">${sub}</p>`;
function stats(){let attempted=0,correct=0;for(const q of D.questions){const a=state.answers[q.id];if(a){attempted++;if(a.correct)correct++;}}return{attempted,correct};}
function weakTopics(){return D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id&&state.answers[q.id]);return{...t,attempted:qs.length,wrong:qs.filter(q=>!state.answers[q.id].correct).length};}).filter(t=>t.wrong).sort((a,b)=>b.wrong-a.wrong);}
function planEntries(){return D.plan.map((entry,index)=>({entry,index})).filter(({entry})=>!entry[3].startsWith('writing'));}
function completedPlanCount(){return planEntries().filter(({index})=>state.plan[index]).length;}

const MISSIONS=[
 {id:'time',icon:'↶',name:'Zeitreise',sub:'Springe zwischen gestern, heute und morgen.',topics:['present','past','perfect','future'],color:'rose'},
 {id:'detective',icon:'?',name:'Satzdetektiv',sub:'Finde die richtige Spur im Satz.',topics:['questions','pronouns','relatives','connectors','modals'],color:'blue'},
 {id:'workshop',icon:'Aa',name:'Wortwerkstatt',sub:'Setze Wörter und Formen passend zusammen.',topics:['comparison','quantifiers','prepositions','plural','words'],color:'gold'}
];
function missionStars(correct){return correct===5?3:correct>=3?2:correct>=1?1:0;}
function bestStars(id){return Math.max(0,Math.min(3,Number(state.missions[id])||0));}
function starLine(n){return `<span class="star-line" role="img" aria-label="${n} von 3 Sternen">${[1,2,3].map(i=>`<span class="${i<=n?'filled':''}" aria-hidden="true">${i<=n?'★':'☆'}</span>`).join('')}</span>`;}
function missionBoard(){return `<section class="mission-board" aria-labelledby="mission-heading"><div class="row"><h2 id="mission-heading">Wähle deine Mission</h2><span class="pill accent">${MISSIONS.reduce((n,m)=>n+bestStars(m.id),0)} / 9 Sterne</span></div><p class="meta">5 Fragen pro Mission · ohne Zeitdruck · neue Fragen zuerst</p><div class="mission-grid">${MISSIONS.map(m=>`<article class="mission-card ${m.color}"><span class="mission-icon" aria-hidden="true">${m.icon}</span><h3>${m.name}</h3><p>${m.sub}</p>${starLine(bestStars(m.id))}${button('Mission starten','start:mission:'+m.id,'primary',`aria-label="Mission ${m.name} starten"`)}</article>`).join('')}</div><p class="meta small-gap">1 richtige Antwort = 1 Stern · 3 richtige = 2 Sterne · alle 5 = 3 Sterne. Dein bester Stand bleibt erhalten.</p></section>`;}

function topicProgress(id){const qs=D.questions.filter(q=>q.topic===id),n=qs.filter(q=>{const a=state.answers[q.id];return a&&(a.correct||a.everCorrect||a.firstCorrect);}).length;const thresholds=[Math.ceil(qs.length/3),Math.ceil(qs.length*2/3),qs.length];return{correct:n,total:qs.length,stars:thresholds.filter(t=>n>=t).length,next:thresholds.find(t=>t>n)};}
function topicSummary(){const stars=D.grammar.reduce((n,t)=>n+topicProgress(t.id).stars,0);return `<section class="grammar-stars"><span class="big-star" aria-hidden="true">★</span><div><h2>Deine Grammatiksterne</h2><p><strong>${stars} / ${D.grammar.length*3} Sterne</strong> · bis zu 3 pro Thema</p><p class="meta">5, 10 und 14 verschiedene Aufgaben eines Themas richtig lösen. Jede Aufgabe zählt einmal, auch in Missionen. Verdiente Sterne bleiben erhalten.</p></div><a href="#progress">Sternesammlung ansehen →</a></section>`;}
const EXERCISE_NAMES={input:'Selbst schreiben',choice:'Auswählen',order:'Satzpuzzle',error:'Fehler finden'};
function exerciseState(q){const s=state.session;s.exerciseUI??={};const u=s.exerciseUI[q.id]??={value:'',picked:[]};if(!Array.isArray(u.picked))u.picked=[];if(!u.bank&&q.type==='order')u.bank=shuffled(q.parts.map((_,i)=>i));if(!u.options&&q.type==='choice')u.options=shuffled(q.options.map((_,i)=>i));return u;}
function exerciseInput(q,r){const s=state.session,u=exerciseState(q);
 if(q.type==='choice')return `<fieldset class="answer-choices"><legend>Welche Antwort passt?</legend>${u.options.map(i=>`<label class="choice" for="option-${i}"><input id="option-${i}" name="exercise-choice" type="radio" data-exercise-option="${i}" value="${E(q.options[i])}" ${(r?r.answer:u.value)===q.options[i]?'checked':''} ${r?'disabled':''}><span lang="en">${E(q.options[i])}</span></label>`).join('')}</fieldset>`;
 if(q.type==='error')return `<div class="error-parts" role="group" aria-label="Fehlerstelle auswählen">${q.parts.map((part,i)=>`<button class="word-chip" type="button" data-action="error-pick:${i}" aria-pressed="${(r?r.answer:u.value)===part}" ${r?'disabled':''} lang="en">${E(part)}</button>`).join('')}</div><p class="meta small-gap" aria-live="polite">${u.value?'Ausgewählt: '+E(u.value):'Tippe auf den fehlerhaften Baustein und prüfe deine Auswahl.'}</p>`;
 if(q.type==='order')return `<div class="puzzle-answer" role="group" aria-label="Dein zusammengesetzter Satz">${u.picked.length?u.picked.map((i,pos)=>`<button type="button" class="word-chip placed" data-action="puzzle-remove:${pos}" ${r?'disabled':''} aria-label="${E(q.parts[i])} zurücklegen" lang="en">${E(q.parts[i])}</button>`).join(''):'<span class="meta">Hier entsteht dein Satz …</span>'}</div><p class="meta puzzle-count" aria-live="polite">${u.picked.length} von ${q.parts.length} Bausteinen eingesetzt</p><div class="puzzle-bank" role="group" aria-label="Verfügbare Satzbausteine">${u.bank.map(i=>`<button type="button" class="word-chip" data-action="puzzle-add:${i}" ${r||u.picked.includes(i)?'disabled':''} lang="en">${E(q.parts[i])}</button>`).join('')}</div>${button('Satz neu legen','puzzle-clear','text',r?'disabled':'')}`;
 return `<div class="field answer-input"><label for="answer">Deine Antwort</label><input type="text" id="answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" ${r?'readonly':''} value="${E(r?.answer||(s.inputDraftIndex===s.index?s.inputDraft:'')||'')}" aria-describedby="answer-hint"></div><p id="answer-hint" class="meta small-gap">Trage die gesuchte Form oder Wortgruppe ein.</p>`;
}
function practiceAnswer(){const s=state.session,q=D.questions.find(q=>q.id===s.ids[s.index]);if(q.type==='input'||!q.type)return $('#answer')?.value||'';const u=exerciseState(q);return q.type==='order'?u.picked.map(i=>q.parts[i]).join(' '):u.value;}
function exerciseAction(action,value){const s=state.session,q=s&&D.questions.find(q=>q.id===s.ids[s.index]);if(!q||s.responses[q.id])return;const u=exerciseState(q),i=Number(value);let focus='';
 if(action==='error-pick'&&q.type==='error'&&Number.isInteger(i)&&q.parts[i]!==undefined){u.value=q.parts[i];focus=`[data-action="error-pick:${i}"]`;}
 else if(action==='puzzle-add'&&q.type==='order'&&Number.isInteger(i)&&q.parts[i]!==undefined&&!u.picked.includes(i)){u.picked.push(i);focus=`[data-action="puzzle-remove:${u.picked.length-1}"]`;}
 else if(action==='puzzle-remove'&&q.type==='order'&&Number.isInteger(i)&&u.picked[i]!==undefined){const part=u.picked.splice(i,1)[0];focus=`[data-action="puzzle-add:${part}"]`;}
 else if(action==='puzzle-clear'&&q.type==='order'){u.picked=[];focus='[data-action^="puzzle-add:"]';}else return;
 save();render(false);$(focus)?.focus({preventScroll:true});
}

function earnedBadges(){const answers=D.questions.filter(q=>state.answers[q.id]);return [
 {name:'Losgelegt!',icon:'→',hint:'Beantworte deine erste Frage.',earned:answers.length>0},
 {name:'Entdeckertalent',icon:'✦',hint:'Probiere 5 Grammatikthemen aus.',earned:new Set(answers.map(q=>q.topic)).size>=5},
 {name:'Drangeblieben',icon:'↻',hint:'Löse einen früheren Fehler richtig.',earned:answers.some(q=>state.answers[q.id].recovered)},
 {name:'Sternensammler',icon:'★',hint:'Sammle alle 9 Missionssterne.',earned:MISSIONS.every(m=>bestStars(m.id)===3)}
 ];}
function badgeShelf(){const badges=earnedBadges();return `<section class="badge-shelf" aria-labelledby="badge-heading"><div class="row"><h2 id="badge-heading">Deine Lernabzeichen</h2><span class="meta">${badges.filter(b=>b.earned).length} / ${badges.length} gesammelt</span></div><ul class="badge-list">${badges.map(b=>`<li class="${b.earned?'earned':''}"><span class="badge-token" aria-hidden="true">${b.icon}</span><div><strong>${b.name}</strong><span class="meta">${b.earned?'✓ Gesammelt':b.hint}</span></div></li>`).join('')}</ul></section>`;}
function finishMission(){const s=state.session;if(s?.kind!=='mission'||s.index<s.ids.length)return;const n=s.ids.filter(id=>s.responses[id]?.correct).length;state.missions[s.value]=Math.max(bestStars(s.value),missionStars(n));}
function missionTrail(s){return `<ol class="mission-trail" aria-label="Deine fünf Missionsaufgaben">${s.ids.map((id,i)=>{const r=s.responses[id];const text=r?(r.correct?'richtig':'noch üben'):i<s.index?'übersprungen':i===s.index?'aktuell':'offen';return `<li class="${r?.correct?'solved':i===s.index?'current':''}" ${i===s.index?'aria-current="step"':''}><span aria-hidden="true">${r?.correct?'✓':i+1}</span><span class="sr-only">Aufgabe ${i+1}: ${text}</span></li>`;}).join('')}</ol>`;}

function miloGuide(route){
 const s=state.session,q=s&&D.questions.find(q=>q.id===s.ids[s.index]),r=q&&s.responses[q.id];
 const messages={home:['Hi, ich bin Milo!','Komm, wir schnappen uns fünf Fragen. Welche Mission suchst du dir aus?'],practice:['Schnapp dir eine Mission!','Lieber kurz spielen oder ein Thema genauer üben? Hier findest du beides.'],grammar:['Auf der Spur der richtigen Regel','Lies erst das Beispiel. Dann versuche einen eigenen Satz mit derselben Regel.'],quiz:s&&s.index>=s.ids.length?['Pfote drauf: Jeder Versuch zählt!','Schau dir deine Antworten an. Eine knifflige Stelle kannst du gleich noch einmal üben.']:r?(r.correct?['Das hast du raus!','Lies kurz die Erklärung. So merkst du dir, warum deine Antwort passt.']:['Wir bleiben dran!','Die Erklärung hilft dir weiter. Du kannst die Aufgabe später noch einmal versuchen.']):['Du bist dran!','Lies den ganzen Satz. Brauchst du Hilfe? Die passende Grammatik findest du direkt bei der Aufgabe.'],exams:['Zeit für deine Generalprobe','Wähle einen Originaltest. Hier gehören Hörverstehen, Grammatik und Schreiben zusammen.'],exam:['Jetzt gehört die Bühne dir.','Bearbeite den Originaltest in Ruhe. Deine Antworten werden auf diesem Gerät gespeichert.'],progress:['Schau, was du schon geschafft hast!','Hier findest du deine Abzeichen und siehst, welche Themen noch etwas Übung brauchen.']};
 const [title,message]=messages[route]||messages.home;
 return `<aside class="milo-guide" aria-label="Milo, dein Lernbegleiter"><img src="mascot/milo.png" width="112" height="112" alt="" decoding="async"><div class="milo-bubble"><span class="milo-name">Milo · dein Lernbegleiter</span><strong>${title}</strong><p>${message}</p></div></aside>`;
}
function home(){const s=stats(),weak=weakTopics(),done=completedPlanCount();return head('Dein Englisch-Abenteuer','Entdecke Grammatik, sammle Sterne und mach dich fit für den Test.','English Lab · Klasse 7')+`
 ${state.session&&state.session.index<state.session.ids.length?'<p class="resume-note"><a href="#quiz">→ Angefangene Übung fortsetzen</a></p>':''}
 ${missionBoard()}
 ${topicSummary()}
 <div class="learning-strip"><span class="strip-symbol" aria-hidden="true">✦</span><div><strong>${s.attempted?`${s.correct} Aufgaben zuletzt richtig gelöst`:'Jeder Versuch bringt dich weiter.'}</strong><p class="meta">${weak.length?`Noch knifflig: ${E(weak[0].title)}. Schau dir die Regel an und probiere es wieder.`:'Du darfst nachschlagen, Fehler machen und neu versuchen.'}</p></div><a href="${weak.length?'#grammar/'+weak[0].id:'#grammar'}">${weak.length?'Regel ansehen':'Grammatik nachschlagen'} →</a></div>
 ${badgeShelf()}
 <div class="split"><section><div class="row"><h2>Dein Lernweg</h2><span class="pill" id="plan-count">${done} / ${planEntries().length} Einheiten</span></div><p class="meta">Für längere Runden und deine Generalprobe. Wähle frei und hake ab, was du erledigt hast.</p><div class="learning-path">${planEntries().map(({entry:p,index:i})=>`<div class="plan-row ${state.plan[i]?'done':''}"><input type="checkbox" id="day-${i}" data-plan="${i}" ${state.plan[i]?'checked':''}><label for="day-${i}"><strong>${p[1]}</strong><span class="meta">${p[2]} · ${p[4]} Min.</span></label><a href="${planHref(p[3])}" class="button secondary">Öffnen</a></div>`).join('')}</div></section>
 <aside><div class="panel tint"><span class="section-label">Die Generalprobe</span><h3>Bereit für den ganzen Test?</h3><p class="meta">Die Originaltests 2021–2025 warten auf dich: mit Hörverstehen, Grammatik und Textproduktion.</p><a class="button secondary" href="#exams">Originaltest wählen →</a><p class="meta small-gap">50 Minuten · 60 BE · keine Hilfsmittel. Für deinen aktuellen Test gelten die Vorgaben deiner Lehrkraft.</p></div><div class="panel"><h3>Noch eine Runde?</h3><p class="meta">Du kannst auch ein Thema gezielt üben oder mit zwölf gemischten Fragen starten.</p><a href="#practice">Alle Grammatikübungen →</a></div></aside></div>`;}
function planHref(p){const [a,b]=p.split(':');if(['topic','year'].includes(a))return '#start/'+a+'/'+b;if(a==='diagnostic'||a==='mistakes'||a==='mixed')return '#start/'+a;return '#'+(a==='exams'?'exam':a)+(b?'/'+b:'');}
function practice(){const fresh=D.questions.filter(q=>!q.year).length;return head('Dein Grammatik-Spielplatz','Kurze Mission oder längere Runde? Du entscheidest. Nach jeder Antwort bekommst du eine Erklärung.')+`
 ${missionBoard()}
 ${topicSummary()}
 <section class="panel tint"><h2>${fresh} eigenständige Übungen</h2><p>Neue Sätze zu Schule, Freizeit, Reisen und Alltag. Wähle Antworten aus, baue ganze Sätze, finde Fehler und schreibe eigene Lösungen. Alle vier Formen begegnen dir auch in den Themenrunden.</p><div class="actions">${button('Gemischte Runde starten','start:mixed')}${button('Lerncheck starten','start:diagnostic','secondary')}</div><p class="meta small-gap">Zwölf Aufgaben pro gemischter Runde. Noch nicht bearbeitete Fragen kommen zuerst; danach offene Fehler und bereits gelöste Fragen.</p></section>
 <section class="format-picker"><h2>Worauf hast du Lust?</h2><div class="format-buttons">${[['input','✎','Selbst schreiben'],['choice','✓','Antworten auswählen'],['order','↔','Sätze puzzeln'],['error','⌕','Fehler finden']].map(([id,icon,label])=>button(`<span aria-hidden="true">${icon}</span><span>${label}<small>${D.questions.filter(q=>q.type===id).length} Aufgaben</small></span>`,'start:format:'+id,'secondary')).join('')}</div><p class="meta small-gap">Bis zu 12 Aufgaben aus mehreren Themen. Du sammelst dabei Sterne für das jeweilige Grammatikthema.</p></section>
 <h2>Ein Thema gezielt üben</h2><div class="filters"><div class="field"><label for="practice-topic">Dein Thema</label><select id="practice-topic">${D.grammar.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></div><div class="field"><label for="practice-level">Schwierigkeit</label><select id="practice-level"><option value="new">Alle neuen Übungen</option><option value="basic">Grundlagen festigen</option><option value="apply">Formen anwenden</option><option value="transfer">Wissen übertragen</option></select></div></div><div class="actions">${button('Thema üben','start-selected')}${button('Fehler wiederholen','start:mistakes','secondary')}</div><p class="meta small-gap">Bis zu zwölf Aufgaben pro Themenrunde. „Fehler wiederholen“ enthält deine offenen Fehler aus deinen Grammatikübungen.</p>
 <p class="small-gap"><a href="#exams">Bereit für die Generalprobe? Zu den Originaltests</a></p>
 <h2 style="margin-top:40px">Erst die Regel verstehen?</h2><div class="grammar-index">${D.grammar.map(t=>topicCard(t)).join('')}</div>`;}
function topicCard(t){return `<a class="topic-link" href="#grammar/${t.id}"><h3>${t.title} <span aria-hidden="true">↗</span></h3>${starLine(topicProgress(t.id).stars)}<p class="meta">${topicProgress(t.id).correct} / ${topicProgress(t.id).total} verschiedene Aufgaben richtig gelöst</p><p>${t.sub}</p><p class="meta small-gap">Wiederholung: Klasse ${t.curriculumGrades.join(' & ')}<br>Testbezug des Kapitels: ${t.years.join(', ')}</p></a>`;}
function grammar(id){if(!id||!topic(id))return head('Kurz nachschlagen. Besser verstehen.','Vierzehn Kapitel helfen dir, Lücken aus früheren Klassen zu schließen. Die Beispiele zeigen dir die Regel direkt im Satz.')+`<div class="field"><label for="grammar-search">Thema finden</label><input id="grammar-search" type="search" placeholder="Zum Beispiel: Zeiten, Fragen, much, will …"></div><div class="grammar-index" id="grammar-results">${D.grammar.map(topicCard).join('')}</div>`;const t=topic(id);return `<a class="back" href="#grammar">← Alle Grammatikthemen</a><article class="lesson">${head(t.title,t.sub,`Nachschlagen · Stoff aus Klasse ${t.curriculumGrades.join(' & ')}`)}${starLine(topicProgress(t.id).stars)}<p class="meta">${topicProgress(t.id).correct} / ${topicProgress(t.id).total} Aufgaben für deine Themensterne gelöst</p><p class="rule">${t.rule}</p><h2>Die Regel auf einen Blick</h2><ul>${t.forms.map(f=>`<li>${E(f)}</li>`).join('')}</ul><h2>So sieht das im Satz aus</h2>${t.examples.map(ex=>`<div class="example"><p lang="en">${E(ex[0])}</p><p class="muted">${E(ex[1])}</p></div>`).join('')}<div class="warning"><strong>Typische Stolperfalle</strong><p style="margin:8px 0 0">${E(t.trap)}</p></div><div class="actions">${button('Jetzt dazu üben','start:topic:'+id)}${state.session&&state.session.index<state.session.ids.length?'<a href="#quiz">Zur laufenden Übung</a>':''}</div></article>`;}
function practicePriority(q){const a=state.answers[q.id];return !a?0:a.correct?2:1;}
function shuffled(list){const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
function orderedPractice(list){const pool=shuffled(list),result=[];for(const priority of [0,1,2]){const groups={};for(const q of pool.filter(q=>practicePriority(q)===priority))(groups[q.type||'input']??=[]).push(q);const types=shuffled(Object.keys(groups));while(types.some(t=>groups[t].length))for(const t of types)if(groups[t].length)result.push(groups[t].shift());}return result;}
function questionSet(kind,value,level='new'){
 if(kind==='mission'){const m=MISSIONS.find(m=>m.id===value);return m?orderedPractice(D.questions.filter(q=>m.topics.includes(q.topic))).slice(0,5):[];}
 if(kind==='diagnostic')return D.grammar.slice(0,12).map(t=>D.questions.find(q=>q.topic===t.id&&q.level==='apply'));
 if(kind==='mixed'){const candidates=D.grammar.map(t=>orderedPractice(D.questions.filter(q=>!q.year&&q.topic===t.id))[0]).filter(Boolean);return orderedPractice(candidates).slice(0,12);}
 if(kind==='format')return orderedPractice(D.questions.filter(q=>q.type===value)).slice(0,12);
 if(kind==='year')return D.questions.filter(q=>q.year===+value);
 if(kind==='topic')return orderedPractice(D.questions.filter(q=>!q.year&&q.topic===value&&(level==='new'||level==='all'||q.level===level))).slice(0,12);
 if(kind==='mistakes')return D.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct);
 return [];
}
function startSession(kind,value,level){const qs=questionSet(kind,value,level);if(!qs.length){notify(kind==='mistakes'?'Noch keine offenen Fehler. Starte zuerst eine Übung.':'Für diese Auswahl gibt es keine Aufgaben.');go('practice');return;}state.session={kind,value,ids:qs.map(q=>q.id),index:0,responses:{},started:new Date().toISOString()};save();go('quiz');}
function normalize(v,caseSensitive=false){let s=String(v).trim().replace(/[‘’`]/g,"'").replace(/\s+/g,' ').replace(/[.!?]$/,'');return caseSensitive?s:s.toLowerCase();}
function matchAnswer(q,value){return q.answers.some(a=>normalize(a,q.caseSensitive)===normalize(value,q.caseSensitive));}
function quiz(){const ses=state.session;if(!ses)return head('Womit möchtest du starten?','Wähle eine Übung, um deine Grammatikkenntnisse zu festigen.')+'<a class="button" href="#practice">Übung auswählen</a>';if(ses.index>=ses.ids.length)return results();const q=D.questions.find(q=>q.id===ses.ids[ses.index]),r=ses.responses[q.id],t=topic(q.topic);const title=ses.kind==='format'?EXERCISE_NAMES[ses.value]:ses.kind==='mission'?'Mission: '+MISSIONS.find(m=>m.id===ses.value)?.name:ses.kind==='diagnostic'?'Dein Lerncheck':ses.kind==='mixed'?'Neue gemischte Übungsrunde':ses.kind==='year'?'Originaltraining '+ses.value:ses.kind==='mistakes'?'Deine Fehlerwerkstatt':t.title;return `<a class="back" href="#practice">← Zur Übungsauswahl</a>${head(title,ses.kind==='mission'?'Fünf kleine Rätsel. Nimm dir Zeit und nutze die Regeln, wenn du Hilfe brauchst.':ses.kind==='diagnostic'?'Versuche es zuerst ohne Hilfe. Der Lerncheck ist keine Note.':'Beachte den Arbeitsauftrag. Bei Schreibweisen zählen britische und amerikanische Varianten, soweit angegeben.')}${ses.kind==='mission'?missionTrail(ses):''}<div class="progress-caption"><span>Aufgabe ${ses.index+1} von ${ses.ids.length}</span><span>${Math.round(ses.index/ses.ids.length*100)} % bearbeitet</span></div><progress value="${ses.index}" max="${ses.ids.length}"></progress><div class="study-grid" style="margin-top:24px"><section class="exercise"><p class="pill exercise-kind">${EXERCISE_NAMES[q.type]||EXERCISE_NAMES.input}</p><p class="meta">${E(q.source)} · Stoff aus Klasse ${q.curriculumGrades.join(' & ')}</p>${q.instruction?`<p class="meta">${E(q.instruction)}</p>`:''}<p class="sentence" lang="en">${E(q.prompt).replace('___','<strong aria-label="Lücke">________</strong>')}</p><form id="answer-form">${exerciseInput(q,r)}<div class="actions">${r?button(ses.index===ses.ids.length-1?'Auswertung ansehen':'Nächste Aufgabe','next'): '<button type="submit" class="primary">Antwort prüfen</button>'+button('Überspringen','skip','secondary')}</div></form>${r?feedback(q,r):'<div id="answer-feedback" aria-live="polite"></div>'}</section><aside><div class="panel tint"><h3>Passende Grammatik</h3><p>${E(t.sub)}</p><a href="#grammar/${t.id}">${E(t.title)} nachschlagen</a><p class="meta small-gap">Deine Übung bleibt erhalten.</p></div><p class="meta">${q.year?'Diese Aufgabe stammt aus einem Originaltest und wurde für das Einzeltraining aufbereitet. Den vollständigen Test findest du unter „Originaltests online“.':'Diese Aufgabe wurde neu entwickelt. Sie übt prüfungsrelevante Regeln mit einem anderen Satz oder Kontext.'}</p></aside></div>`;}
function feedback(q,r){return `<div class="feedback ${r.correct?'correct':''}" id="answer-feedback" role="status"><h3>${r.correct?'✓ Treffer! Richtig gelöst.':'Noch knifflig? Knacken wir die Regel.'}</h3>${!r.correct?`<p>${q.type==='error'?'Fehlerstelle':'Passende Antwort'}: <strong lang="en">${E(q.answers[0])}</strong></p>`:''}<p>${E(q.explanation)}</p>${q.correctedSentence?`<p lang="en"><strong>Richtig:</strong> ${E(q.correctedSentence)}</p>`:''}<div class="topic-reward ${r.newTopicStar?'new-star':''}">${starLine(topicProgress(q.topic).stars)}<p><strong>${r.newTopicStar?'Neuer Grammatikstern!':'Deine Themensterne'}</strong><br>${topicProgress(q.topic).correct} / ${topicProgress(q.topic).total} verschiedene Aufgaben gelöst${topicProgress(q.topic).next?` · noch ${topicProgress(q.topic).next-topicProgress(q.topic).correct} bis zum nächsten Stern`: ' · alle 3 Sterne gesammelt!'}</p></div>${q.answers.length>1?`<p class="meta">Auch akzeptiert: ${q.answers.slice(1).map(E).join(' · ')}</p>`:''}<a href="#grammar/${q.topic}">Regel nachschlagen</a></div>`;}
function checkAnswer(value){const s=state.session;if(!s||s.index>=s.ids.length)return;const q=D.questions.find(q=>q.id===s.ids[s.index]);if(s.responses[q.id])return;if(!value.trim()){notify('Gib zuerst eine Antwort ein, wähle etwas aus oder überspringe die Aufgabe.');$('#answer')?.focus();return;}const starsBefore=topicProgress(q.topic).stars;const correct=matchAnswer(q,value),r={answer:value,correct,at:new Date().toISOString()};s.responses[q.id]=r;const old=state.answers[q.id];state.answers[q.id]={...r,attempts:(old?.attempts||0)+1,firstCorrect:old?.firstCorrect??correct,everCorrect:!!(correct||old?.everCorrect||old?.correct||old?.firstCorrect),recovered:!!old?.recovered||!!(old&&!old.correct&&correct)};r.newTopicStar=topicProgress(q.topic).stars>starsBefore;save();render(false);$('#answer-feedback')?.scrollIntoView({block:'nearest'});$('.actions button[data-action="next"]')?.focus();}
function results(){const s=state.session;const qs=s.ids.map(id=>D.questions.find(q=>q.id===id));const correct=qs.filter(q=>s.responses[q.id]?.correct).length;const missed=qs.filter(q=>!s.responses[q.id]?.correct);const skipped=qs.filter(q=>!s.responses[q.id]).length;const topics=[...new Set(missed.map(q=>q.topic))];return head(s.kind==='mission'?'Mission beendet!':'Runde geschafft!', 'Schau dir an, was schon klappt und was du beim nächsten Mal ausprobieren kannst.')+`${s.kind==='mission'?`<section class="mission-finish">${starLine(missionStars(correct))}<h2>${correct===5?'Alle fünf geknackt!':correct>=3?'Gut unterwegs!':correct?'Dein erster Treffer in dieser Runde!':'Ein neuer Versuch wartet auf dich.'}</h2><p>${missionStars(correct)} von 3 Sternen in dieser Runde · Bester Stand: ${bestStars(s.value)} von 3</p><p class="meta">${correct<5?'Mit den Erklärungen kannst du die kniffligen Stellen noch einmal angehen.':'Deine Sterne sind gespeichert. Lust auf eine andere Mission?'}</p>${button('Neue Missionsrunde','start:mission:'+s.value,'secondary')}</section>`:''}<section class="panel tint"><p class="result-number">${correct} von ${qs.length} richtig</p><p>${skipped?`${skipped} Aufgaben übersprungen. `:''}${correct===qs.length?'Diese Runde sitzt. Probiere eine neue gemischte Runde, um dein Wissen in anderen Situationen anzuwenden.':'Lies die Erklärungen und wiederhole die offenen Themen später noch einmal.'}</p><p class="meta">Ergebnis dieser Runde. Keine offizielle Testnote und keine sichere Vorhersage für die Prüfung.</p></section>${topicSummary()}${badgeShelf()}${topics.length?`<h2>Diese Themen lohnen sich</h2><div class="grammar-index">${topics.map(id=>topicCard(topic(id))).join('')}</div>`:''}<h2 style="margin-top:32px">Deine Antworten</h2>${qs.map(q=>{const r=s.responses[q.id];return `<details><summary>${r?.correct?'✓ Richtig':r?'↻ Wiederholen':'○ Übersprungen'} · ${E(topic(q.topic).title)}</summary><p lang="${q.type==='order'?'de':'en'}">${E(q.prompt)}</p><p>Deine Antwort: ${E(r?.answer||'keine Antwort')}</p><p>Passende Antwort: <strong>${E(q.answers[0])}</strong></p><p>${E(q.explanation)}</p></details>`;}).join('')}<div class="actions">${missed.length?button('Offene Aufgaben erneut üben','retry'):''}<a class="button secondary" href="#home">Zum Lernweg</a><a href="#practice">Andere Übung wählen</a></div>`;}
function audioBlock(y){return `<audio controls preload="none" aria-label="Hörtext Originaltest ${y.year}" src="${asset(y.audio)}">Audio nicht unterstützt.</audio><p class="meta">Der Originaltrack enthält beide Teile jeweils zweimal, alle Anweisungen und Pausen. Für die Generalprobe einmal vollständig durchlaufen lassen.</p>`;}
function wordCount(t){return(t.trim().match(/\S+/g)||[]).length;}
function listening(){return head('Hörverstehen im Originaltest','Hörtexte gibt es ausschließlich in den vollständigen Originaltests.')+'<a class="button" href="#exams">Originaltests öffnen</a>';}
function writing(){return head('Grammatik und Originaltests','Textproduktion bearbeitest du im vollständigen Originaltest.')+'<a class="button" href="#exams">Originaltests öffnen</a>';}
function progressPage(){const s=stats();return head('Dein Fortschritt gehört dir.','Alle Angaben bleiben in diesem Browser auf diesem Gerät. Beim Löschen der Browserdaten gehen sie verloren. Es gibt keine Übertragung an deine Lehrkraft.')+`<section class="panel"><h2>${s.correct} Aufgaben zuletzt richtig gelöst</h2><p>${s.attempted} von ${D.questions.length} Aufgaben bearbeitet. Wiederholungen zählen nicht mehrfach.</p><progress value="${s.correct}" max="${D.questions.length}"></progress><p class="meta small-gap">Ein richtig wiederholter Fehler erscheint nicht mehr in der Fehlerwerkstatt.</p><div class="actions">${button('Fehler wiederholen','start:mistakes')}${button('Lernstand herunterladen','export-progress','secondary')}</div></section>${topicSummary()}${badgeShelf()}<h2>Deine Themen im Überblick</h2><ul class="flat-list">${D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id),a=qs.filter(q=>state.answers[q.id]),c=a.filter(q=>state.answers[q.id].correct);return`<li><div class="row"><div><a href="#grammar/${t.id}">${t.title}</a><br>${starLine(topicProgress(t.id).stars)}<div class="meta">${topicProgress(t.id).correct} / ${topicProgress(t.id).total} für die Themensterne</div><div class="meta">${a.length?`${c.length} zuletzt richtig · ${a.length} bearbeitet`:'Noch nicht geübt'}</div></div><a href="#start/topic/${t.id}">Üben</a></div></li>`;}).join('')}</ul><section class="panel" style="margin-top:32px"><h2>Daten auf diesem Gerät</h2><p class="meta">Gespeichert werden Antworten, vollständige Online-Testbögen, angehakte Lerneinheiten, Schreibtexte in den Tests, selbst eingetragene Punkte und die Timer. Kein Name erforderlich. An einem gemeinsam genutzten Gerät können andere diese Inhalte sehen.</p><p class="meta">${storageOK?'Lokales Speichern ist verfügbar.':'Lokales Speichern ist derzeit nicht verfügbar. Nutze die Downloads, bevor du die Seite schließt.'}</p><details><summary>Gesamten Lernstand zurücksetzen</summary><p>Damit löschst du auch alle hier gespeicherten Texte und Testergebnisse. Lade sie vorher herunter.</p>${button('Alle lokalen Lerndaten endgültig löschen','reset-progress','secondary')}</details></section>`;}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function render(focus=true){const [route='home',a,b]=location.hash.slice(1).split('/');if(route==='start'){startSession(a,b);return;}const makers={home,practice,grammar,listening,writing,exams:onlineExamLibrary,exam:onlineTest,progress:progressPage,quiz};const maker=makers[route]||home;const content=maker(a);$('#main').innerHTML=content.replace(/(<p class="intro">.*?<\/p>)/,'$1'+miloGuide(route));document.body.dataset.learningPage=route==='exam'?'exam':'practice';document.querySelectorAll('[data-nav]').forEach(n=>{const active=n.dataset.nav===(route==='quiz'?'practice':route==='exam'?'exams':route);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);} }
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,a,v]=b.dataset.action.split(':');if(action==='error-pick'||action.startsWith('puzzle-')){exerciseAction(action,a);return;}if(action==='start'){startSession(a,v);return;}if(action==='start-selected'){startSession('topic',$('#practice-topic').value,$('#practice-level').value);return;}if(action==='next'||action==='skip'){state.session.index++;finishMission();save();render();return;}if(action==='retry'){const s=state.session;const ids=s.ids.filter(id=>!s.responses[id]?.correct);state.session={kind:'mistakes',ids,index:0,responses:{},started:new Date().toISOString()};save();render();return;}if(action==='export-progress'){const s=stats();download('English-Lab-Lernstand.txt',`English Lab · Lernstand vom ${new Date().toLocaleDateString('de-DE')}\n${s.correct} zuletzt richtig, ${s.attempted} bearbeitet.\nGrammatiksterne: ${D.grammar.reduce((n,t)=>n+topicProgress(t.id).stars,0)} / 42\n${D.grammar.map(t=>t.title+': '+topicProgress(t.id).stars+' Sterne').join('\n')}\n\n`+D.questions.filter(q=>state.answers[q.id]).map(q=>`${state.answers[q.id].correct?'Richtig':'Wiederholen'}: ${q.prompt}\nDeine Antwort: ${state.answers[q.id].answer}\nRegel: ${q.explanation}`).join('\n\n')+'\n\nABGEHAKTE LERNEINHEITEN\n'+planEntries().filter(({index})=>state.plan[index]).map(({entry})=>entry[1]).join('\n'));return;}if(action==='reset-progress'&&window.confirm('Alle Antworten, Texte, Notizen und Fortschritte auf diesem Gerät endgültig löschen?')){state=defaults();save();render();notify('Dein lokaler Lernstand wurde gelöscht.');}});
document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();const q=D.questions.find(q=>q.id===state.session.ids[state.session.index]);if(q.type==='order'&&exerciseState(q).picked.length!==q.parts.length){notify('Lege zuerst alle Bausteine in deinen Satz.');return;}checkAnswer(practiceAnswer());}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='answer'&&state.session&&!el.readOnly){state.session.inputDraft=el.value;state.session.inputDraftIndex=state.session.index;save();}if(el.id==='grammar-search'){const val=el.value.toLocaleLowerCase('de');const matches=D.grammar.filter(t=>JSON.stringify(t).toLocaleLowerCase('de').includes(val));$('#grammar-results').innerHTML=matches.length?matches.map(topicCard).join(''):'<p class="empty">Kein Thema gefunden. Versuche „Zeiten“, „if“ oder „Pronomen“.</p>';}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.exerciseOption!==undefined){const s=state.session,q=D.questions.find(q=>q.id===s.ids[s.index]);if(!s.responses[q.id]&&q.type==='choice'){exerciseState(q).value=q.options[Number(el.dataset.exerciseOption)];save();}return;}if(el.dataset.plan!==undefined){state.plan[el.dataset.plan]=el.checked;save();el.closest('.plan-row').classList.toggle('done',el.checked);if($('#plan-count'))$('#plan-count').textContent=completedPlanCount()+' / '+planEntries().length+' Einheiten';}});
// Keep an unsubmitted answer when consulting a rule or navigating away.
window.addEventListener('hashchange',()=>render());
render(false);
// Optional native agent interface; shares the visible practice flow.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_grammar_practice',title:'Grammatikübung starten',description:'Öffnet eine Grammatikübung zu einem verfügbaren Thema und ersetzt die laufende Übungsrunde. Bereits gespeicherte Ergebnisse bleiben erhalten.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:D.grammar.map(t=>t.id)}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='topic')||!topic(input.topic))throw new Error('Unbekanntes Grammatikthema.');startSession('topic',input.topic);render(false);return{topic:input.topic,questions:state.session.ids.length};}})).catch(()=>{});}catch{}}
